 "content": "from collections import Counter, deque

def transform(grid):
    h, w = len(grid), len(grid[0])
    counts = Counter(v for row in grid for v in row)
    bg = counts.most_common(1)[0][0]
    seen = set()
    comps = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] == bg or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            comp = []
            while q:
                y, x = q.popleft()
                comp.append((y, x, grid[y][x]))
                for yy, xx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                    if 0 <= yy < h and 0 <= xx < w and grid[yy][xx] != bg and (yy,xx) not in seen:
                        seen.add((yy,xx)); q.append((yy,xx))
            comps.append(comp)
    motif_comp = max(comps, key=len)
    minr = min(p[0] for p in motif_comp); maxr = max(p[0] for p in motif_comp)
    minc = min(p[1] for p in motif_comp); maxc = max(p[1] for p in motif_comp)
    cr, cc = (minr + maxr)//2, (minc + maxc)//2
    motif = [(r-cr, c-cc, v) for r,c,v in motif_comp]
    markers = [p for comp in comps if comp is not motif_comp for p in comp]
    out = [row[:] for row in grid]
    for r,c,_ in markers:
        out[r][c] = bg
    for r,c,_ in markers:
        for dr,dc,v in motif:
            rr,cc2 = r+dr,c+dc
            if 0 <= rr < h and 0 <= cc2 < w:
                out[rr][cc2] = v
    return out
